/**
 * Download the Full Audit PDF generated by the backend.
 *
 *   GET {API}/pdf/:projectId/download[?auditNumber=N]
 *
 * One authenticated request; the response body is the PDF itself. Nothing is
 * rendered or assembled in the browser.
 */

export class PdfDownloadError extends Error {
  constructor(message, { code = 'PDF_DOWNLOAD_FAILED', status = null } = {}) {
    super(message);
    this.name = 'PdfDownloadError';
    this.code = code;
    this.status = status;
  }
}

const FALLBACK_FILENAME = 'odito-full-audit.pdf';

/** Safe filename from a Content-Disposition header (ASCII slug only), else a fallback. */
export function filenameFromDisposition(header, fallback = FALLBACK_FILENAME) {
  const m = /filename="?([^";]+)"?/i.exec(header || '');
  const raw = m ? m[1] : '';
  const safe = raw.replace(/[^A-Za-z0-9._-]/g, '').replace(/^\.+/, '');
  return /\.pdf$/i.test(safe) && safe.length > 4 ? safe.slice(0, 120) : fallback;
}

/** Customer-facing message for a failed download, by HTTP status / backend error code. */
export function messageForFailure(status, code, serverMessage) {
  if (status === 401) return 'Your session has expired. Please sign in again and retry the export.';
  if (status === 403) return 'You do not have access to this project, so its report cannot be exported.';
  if (status === 404) {
    if (code === 'AUDIT_NOT_FOUND') return 'The requested audit could not be found for this project.';
    // Only a JSON body that names the project proves the PROJECT is missing. Any other 404
    // (e.g. Express's plain "Cannot GET" page) means this endpoint is not served at all.
    if (code === 'PROJECT_NOT_FOUND' || /project/i.test(serverMessage || '')) return 'This project could not be found.';
    return 'PDF export is not available on the server (the download endpoint was not found). The backend may need to be updated or restarted.';
  }
  if (status === 400) return serverMessage || 'The export request was not valid.';
  if (status === 503) return serverMessage || 'The PDF service is busy or unavailable. Please try again in a moment.';
  if (status === 504) return 'Generating the PDF took too long. Please try again.';
  if (status && status >= 500) return serverMessage || 'The PDF could not be generated. Please try again.';
  return serverMessage || 'The PDF export failed.';
}

/**
 * @param {string} projectId
 * @param {{ auditNumber?: number|null, signal?: AbortSignal, baseURL: string, getToken?: () => string|null, fetchImpl?: typeof fetch }} opts
 * @returns {Promise<{ blob: Blob, filename: string }>}
 */
export async function fetchAuditPdf(projectId, { auditNumber = null, signal, baseURL, getToken, fetchImpl } = {}) {
  if (!projectId || projectId === 'undefined' || projectId === 'all') {
    throw new PdfDownloadError('Select a project before exporting.', { code: 'INVALID_PROJECT' });
  }
  if (auditNumber != null && !(Number.isInteger(auditNumber) && auditNumber > 0)) {
    throw new PdfDownloadError('The audit number must be a positive whole number.', { code: 'INVALID_AUDIT_NUMBER' });
  }
  const doFetch = fetchImpl || fetch;
  const token = (getToken ? getToken() : (typeof window !== 'undefined' ? window.localStorage.getItem('token') : null)) || null;
  const qs = auditNumber != null ? `?auditNumber=${encodeURIComponent(auditNumber)}` : '';
  const url = `${baseURL}/pdf/${encodeURIComponent(projectId)}/download${qs}`;

  let response;
  try {
    response = await doFetch(url, {
      method: 'GET',
      headers: { Accept: 'application/pdf', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      signal,
    });
  } catch (err) {
    if (err?.name === 'AbortError') throw err;
    throw new PdfDownloadError('Could not reach the server. Check your connection and try again.', { code: 'NETWORK' });
  }

  const type = (response.headers.get('content-type') || '').toLowerCase();
  if (!response.ok) {
    let body = null;
    try { body = type.includes('json') ? await response.json() : null; } catch { body = null; }
    const code = body?.error?.code || body?.code || null;
    const msg = body?.error?.message || body?.message || null;
    throw new PdfDownloadError(messageForFailure(response.status, code, msg), { code: code || 'HTTP_ERROR', status: response.status });
  }
  if (!type.includes('application/pdf')) {
    throw new PdfDownloadError('The server did not return a PDF. Please try again.', { code: 'NOT_A_PDF', status: response.status });
  }
  const blob = await response.blob();
  if (!blob || blob.size === 0) {
    throw new PdfDownloadError('The server returned an empty PDF. Please try again.', { code: 'EMPTY_PDF', status: response.status });
  }
  return { blob, filename: filenameFromDisposition(response.headers.get('content-disposition')), pages: Number(response.headers.get('x-report-pages')) || null };
}

/** Trigger the browser download for a Blob, then release the object URL. */
export function saveBlob(blob, filename, { doc = document, urlApi = URL, revokeDelayMs = 1000 } = {}) {
  const href = urlApi.createObjectURL(blob);
  const a = doc.createElement('a');
  a.href = href;
  a.download = filename;
  a.style.display = 'none';
  doc.body.appendChild(a);
  try {
    a.click();
  } finally {
    a.remove();
    // Revoke after the browser has had time to start the download.
    setTimeout(() => urlApi.revokeObjectURL(href), revokeDelayMs);
  }
}
